package ncasa.expense.application.plan;
import java.time.*;import java.util.UUID;import java.util.function.Consumer;import ncasa.expense.application.*;import ncasa.expense.application.port.out.*;import ncasa.expense.domain.*;
public final class ExpensePlanLifecycleUseCase{public enum Action{PAUSE,REACTIVATE,CANCEL}private final ExpensePlanRepository plans;private final HouseholdExpenseAccessPort access;private final TransactionalOutboxPort outbox;private final Clock clock;public ExpensePlanLifecycleUseCase(ExpensePlanRepository p,HouseholdExpenseAccessPort a,TransactionalOutboxPort o,Clock c){plans=p;access=a;outbox=o;clock=c;}public ExpensePlanView execute(Long actor,UUID householdId,UUID planId,long version,Action action,String reason){var h=new HouseholdRef(householdId);var context=access.getContext(h,actor);var plan=plans.findByIdAndHousehold(new ExpensePlanId(planId),h).orElseThrow(ExpensePlanNotFoundException::new);if(plan.version()!=version)throw new ExpensePlanConflictException("Expense plan changed concurrently");if(!context.administrator()&&!context.actorMemberId().equals(plan.createdByMemberId()))throw new ExpenseAccessDeniedException("Only the creator or an administrator can manage an expense plan");switch(action){case PAUSE->plan.pause(reason,clock.instant());case REACTIVATE->plan.reactivate(LocalDate.now(clock.withZone(plan.zoneId())),clock.instant());case CANCEL->plan.cancel(reason,clock.instant());}var saved=plans.save(plan);outbox.append(plan.id(),plan.pullEvents());return ExpensePlanView.from(saved);}}
